  const resp = await fetch(url, init);
  const text = await resp.text();
  return { status: resp.status, text, headers: resp.headers };
}

function buildMultipart(fields) {
  const boundary = '----RWSDK-TEST-BOUNDARY-XYZ';
  const parts = [];
  for (const [name, value] of Object.entries(fields)) {
    parts.push(`--${boundary}\r\n`);
    parts.push(`Content-Disposition: form-data; name="${name}"\r\n\r\n`);
    parts.push(`${value}\r\n`);
  }
  parts.push(`--${boundary}--\r\n`);
  return {
    body: parts.join(''),
    contentType: `multipart/form-data; boundary=${boundary}`,
  };
}

async function reset() {
  const r = await post(`${HOST}/todos.reset`, {
    method: 'POST',
  });
  console.log('RESET', r.status, JSON.stringify(r.text));
  return r;
}

async function getJson() {
  const r = await post(`${HOST}/todos.json`, { method: 'GET' });
  console.log('JSON ', r.status, r.text);
  return JSON.parse(r.text);
}

